import React, { useEffect, useState } from 'react'
import ClosedOrdersTable from './ClosedOrdersTable'
import DraftOrdersTable from './DraftOrdersTable'
import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import { getLoggedInUser } from '../../../helpers/authUtils';
import { deleteDraftOrder, retrieveDraftCustomerOrders, saveDraftOrder } from '../../../helpers/retailerHelpers';
import DraftOrdersFormModal from './DraftOrdersFormModal';
import { Tab, Tabs } from "@heroui/react";
import ordersApi from '../../../api/orders/ordersApi';
import { Loading, YesNoModal } from '../../../components';
import usersApi from '../../../api/usersApi';
import { availableReferenceNumbers, retrieveReferenceNumbers, saveReferenceNumbers } from '../../../helpers/referenceNumbersHelpers';
import 'react-toastify/dist/ReactToastify.css';
import { ToastContainer, toast } from "react-toastify";
const closedOrderColumns = [
  { name: "Reference", uid: "reference_number" },
  { name: "Is Paid", uid: "is_paid" },
  { name: "Payment Method", uid: "selected_payment_method_title" },
  { name: "Ref", uid: "provider_reference_number" },
  { name: "Payment Description", uid: "payment_description" },
  { name: "Customer Name", uid: "customer_name" },
  { name: "Customer Phone", uid: "customer_phone" },
  { name: "Order Total", uid: "order_price_total" },
  { name: "Order Origin", uid: "order_origin" },
  { name: "Time Created", uid: "created" },
  { name: "Actions", uid: "actions" },
];

const draftOrderColumns = [
  { name: "Reference ", uid: "document_number" },
  { name: "Customer Name", uid: "customer_name" },
  { name: "Customer Phone", uid: "customer_phone" },
  { name: "Order Total", uid: "order_net_price_total" },
  { name: "Time Created", uid: "created" },
  { name: "Actions", uid: "actions" },
];
function OrdersList() {

    const [openDraftOrderFormModal, setopenDraftOrderFormModal] = useState(false)
    const [openClosedtFormModal, setopenClosedFormModal] = useState(false)
    const navigate = useNavigate()
    const [closedOrder, setClosedOrder] = useState()
    const [closedOrders, setClosedOrders] = useState([])
    const [closedOrdersdata, setClosedOrdersData] = useState([])
    const [draftOrdersdata, setDraftOrdersData] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const closedOrdersActionsApi = useApi(ordersApi.ordersActionAdmin)
  const [selected, setSelected] = React.useState("complete-orders");
    const [draftCustomerOrders, setdraftCustomerOrders] = useState([]);
    const [draftOrderToDelete, setdraftOrderToDelete] = useState()

    const [showYesNoModal, setshowYesNoModal] = useState(false)
    const [selectedDates, setSelectedDates] = useState();


    const [user, setUser] = useState()
    const loggedInUser = getLoggedInUser();

    useEffect(() => {
        setdraftCustomerOrders(retrieveDraftCustomerOrders);
    }, []);


    useEffect(() => {


        console.log("Dates", selectedDates);
    }, [selectedDates])
    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getEntityCustomerOrders = async (user) => {
        setClosedOrders([])
        await closedOrdersActionsApi.request({
            "action": "RetrieveEntityOrders"

        })
    }


    const referenceNumbersApi = useApi(usersApi.referenceNumberAction);

    const generateReferenceNumbers = async () => {


        await referenceNumbersApi.request({
            "action": "GenerateBatchReferenceNumbers",
            "limit": 5,
            "entity": loggedInUser.entity_id

        })

    }

    useEffect(() => {


        const available = availableReferenceNumbers()
        console.log("Available refs", available)
        if (available < 1) {
            generateReferenceNumbers()

        }

    }, [])


    // useEffect(() => {

    //     const available_refs=availableReferenceNumbers()
    //     if(available_refs>0){
    //         toast.success("We have refs")
    //         if(referenceNumber===null){
    //         const ref = retrieveReferenceNumbers();

    //         setreferenceNumber(ref["name"])

    //     }  
    //     }

    // }, [])



    useEffect(() => {
        if (referenceNumbersApi.data) {
            if (referenceNumbersApi.data.reference_numbers && referenceNumbersApi.data.reference_numbers.length) {
                saveReferenceNumbers(referenceNumbersApi.data.reference_numbers)

            }
        }
        console.log("referenceNumbersApi.data", referenceNumbersApi.data)
    }, [referenceNumbersApi.data])





    const getEntityCustomerOrdersByDate = async (user) => {
        setClosedOrders([])
        await closedOrdersActionsApi.request({
            "action": "RetrieveEntityOrders",
            "filters": {
                "from_date": selectedDates ? selectedDates[0] : "",
                "to_date": selectedDates ? selectedDates[1] : ""
            }
        })
    }

    useEffect(() => { console.log("drafts", draftCustomerOrders) }, [draftCustomerOrders])


    useEffect(() => {
        getEntityCustomerOrders()
    }, [])

    useEffect(() => {
        if (selectedDates) {
            getEntityCustomerOrdersByDate()
        }

    }, [selectedDates])

    useEffect(() => {
        getEntityCustomerOrders()
        setdraftCustomerOrders(retrieveDraftCustomerOrders);
    }, [openDraftOrderFormModal])


    const handleEditAction = (item) => {

        setopenDraftOrderFormModal(true)

        // setUpdated(false)

        setClosedOrder(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddDraftOrderAction = () => {
      setopenDraftOrderFormModal(true);
      setopenClosedFormModal(true);

      setUpdated(false);

      setmodalTitle("Add new draft order");
      setClosedOrder(null);

      // const ref = retrieveReferenceNumbers();

      // if(ref && ref["name"]){

      //             toast.success(ref["name"]);
      // setreferenceNumber(ref["name"]);

      // setopenDraftOrderFormModal(true)
      // setopenClosedFormModal(true)

      // setUpdated(false)

      // setmodalTitle("Add new draft order")
      // setClosedOrder(null)
      // }else{
      //     generateReferenceNumbers();
      //     return;
      // }
    };
    const handleViewClosedAction = () => {
      setopenDraftOrderFormModal(true);
      setopenClosedFormModal(true);

      setUpdated(false);

      setmodalTitle("Add new department");
      setClosedOrder(null);
    };
    const handleDetailsAction = (item) => {
      navigate(`/retailers/orders/invoice/${item.id}`, {
        state: {
          item: item,
        },
      });
    };
    const handleDeleteAction = (item) => {
      // navigate(`/retailers/departments/delete/${item.id}`)
    };

    useEffect(() => {
      if (closedOrdersActionsApi.data && closedOrdersActionsApi.data.length) {
        setClosedOrders(closedOrdersActionsApi.data);
      }

      console.log("closedOrdersActionsApi.data", closedOrdersActionsApi.data);
    }, [closedOrdersActionsApi.data]);

    useEffect(() => {}, [openDraftOrderFormModal, openClosedtFormModal]);

    //Filtering data
    useEffect(() => {
      setClosedOrdersData(closedOrders);
    }, [closedOrders]);

    useEffect(() => {
      setDraftOrdersData(draftCustomerOrders);
    }, [draftCustomerOrders]);

    const handleFilterClosedOrders = (e) => {
      const search_param = e;

      if (
        closedOrders &&
        closedOrders.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setClosedOrdersData(
          closedOrders.filter((x) =>
            x.customer_name.toLowerCase().includes(search_param)
          )
        );
      } else {
        setClosedOrdersData(closedOrdersActionsApi.data);
      }
    };

    const handleFilterDraftOrders = (e) => {
      const search_param = e;

      if (
        draftCustomerOrders &&
        draftCustomerOrders.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setDraftOrdersData(
          draftCustomerOrders.filter((x) =>
            x.customer_name.toLowerCase().includes(search_param)
          )
        );
      } else {
        setDraftOrdersData(draftCustomerOrders);
      }
    };

    const handleShowDeleteDialog = (e) => {
      console.log("Delete", e);
      setshowYesNoModal(true);
      setdraftOrderToDelete(e);
    };

    const handleDeleteDraftOrder = async () => {
      if (draftOrderToDelete) {
        const res = await deleteDraftOrder(draftOrderToDelete.draft_id);
        if (res) {
          setdraftOrderToDelete(null);
          // console.log('resss', res)
          setshowYesNoModal(false);
          setdraftCustomerOrders(retrieveDraftCustomerOrders);
        }
      }
    };

    const handleEditDraftOrderAction = (e) => {
      console.log("order to populate", e);
      navigate(`/retailers/orders/draft/${e.draft_id}`);
    };
    return (
      <div>
        <ToastContainer position="bottom-center" theme="colored" />
        <YesNoModal
          showModal={showYesNoModal}
          header="Delete Draft Order"
          content="Action is irreversible!"
          setShowModal={setshowYesNoModal}
          yesAction={handleDeleteDraftOrder}
        />
        <Tabs
          fullWidth
          size="md"
          aria-label="Tabs form"
          defaultSelectedKey={selected}
          onSelectionChange={setSelected}
        >
          <Tab key="complete-orders" title="Complete Customer Orders">
            <ClosedOrdersTable
              data={closedOrdersdata}
              columns={closedOrderColumns}
              editAction={handleEditAction}
              detailsAction={handleDetailsAction}
              deleteAction={handleDeleteAction}
              handleFilter={handleFilterClosedOrders}
              selectedDates={selectedDates}
              setSelectedDates={setSelectedDates}
            />
          </Tab>
          <Tab key="draft-orders" title="Draft Customer Orders">
            {openDraftOrderFormModal && (
              <DraftOrdersFormModal
                openEditModal={openDraftOrderFormModal}
                setopenEditModal={setopenDraftOrderFormModal}
                item={closedOrder}
                modalTitle={modalTitle}
              />
            )}
            <DraftOrdersTable
              data={draftOrdersdata}
              columns={draftOrderColumns}
              editAction={handleEditDraftOrderAction}
              detailsAction={handleDetailsAction}
              deleteAction={handleShowDeleteDialog}
              addAction={handleAddDraftOrderAction}
              handleFilter={handleFilterDraftOrders}
            />
          </Tab>

        </Tabs>
      </div>
    );
}

export default OrdersList