class CustomerOrder {
  constructor(
    id,
    draft_id,
    reference_number,
    entity,
    entity_name,
    customer,
    customer_name,
    customer_phone,
    account,
    account_name,
    owner,
    owner_name,
    dependant,
    dependant_name,
    order_price_total,
    order_tax_total,
    order_discount_total,
    order_net_price_total,
    shipping_cost,
    created,
    retailer_payment,
    orderItems = [],
    payment_method
  ) {
    this.id = id;
    this.draft_id = draft_id;
    this.reference_number = reference_number;
    this.entity = entity;
    this.entity_name = entity_name;
    this.customer = customer;
    this.customer_name = customer_name;
    this.customer_phone = customer_phone;
    this.account = account;
    this.account_name = account_name;
    this.owner = owner;
    this.owner_name = owner_name;
    this.dependant = dependant;
    this.dependant_name = dependant_name;
    this.order_price_total = order_price_total;
    this.order_tax_total = order_tax_total;
    this.order_discount_total = order_discount_total;
    this.shipping_cost = shipping_cost;
    this.order_net_price_total = order_net_price_total;
    this.created = created;
    this.retailer_payment = retailer_payment;
    this.orderItems = orderItems;
    this.payment_method = payment_method;
  }
}

export default CustomerOrder;
